contracts/AMMFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

import "./AMMPair.sol";

contract AMMFactory {
    mapping(address => mapping(address => address)) public getPair;
    address[] public allPairs;
    address public admin;

    event PairCreated(address indexed tokenA, address indexed tokenB, address pair, uint);

    constructor() {
        admin = msg.sender;
    }

    function createPair(address tokenA, address tokenB) external returns (address pair) {
        require(tokenA != tokenB, "IDENTICAL");
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), "ZERO");
        require(getPair[token0][token1] == address(0), "EXISTS");

        bytes memory bytecode = type(AMMPair).creationCode;
        bytes32 salt = keccak256(abi.encodePacked(token0, token1));
        assembly {
            pair := create2(0, add(bytecode, 32), mload(bytecode), salt)
        }
        AMMPair(pair).initialize(token0, token1);
        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair;
        allPairs.push(pair);
        emit PairCreated(token0, token1, pair, allPairs.length);
    }

    function allPairsLength() external view returns (uint) {
        return allPairs.length;
    }
}

contracts/AMMPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

import "./IERC20Minimal.sol";

contract AMMPair {
    address public token0;
    address public token1;

    uint112 private reserve0; // token0 reserve
    uint112 private reserve1; // token1 reserve

    // LP token ERC20-like
    string public constant name = "AMM LP Token";
    string public constant symbol = "AMM-LP";
    uint8 public constant decimals = 18;
    uint public totalSupply;
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    bool private initialized;

    // Events
    event Mint(address indexed sender, uint amount0, uint amount1, address indexed to);
    event Burn(address indexed sender, uint amount0, uint amount1, address indexed to);
    event Swap(
        address indexed sender,
        uint amount0In,
        uint amount1In,
        uint amount0Out,
        uint amount1Out,
        address indexed to
    );
    event Sync(uint112 reserve0, uint112 reserve1);
    event Transfer(address indexed from, address indexed to, uint value);
    event Approval(address indexed owner, address indexed spender, uint value);

    // -----------------------
    // Setup
    // -----------------------
    function initialize(address _token0, address _token1) external {
        require(!initialized, "ALREADY_INITIALIZED");
        token0 = _token0;
        token1 = _token1;
        initialized = true;
    }

    // -----------------------
    // LP Token ERC20-like
    // -----------------------
    function approve(address spender, uint value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint value) external returns (bool) {
        require(balanceOf[msg.sender] >= value, "INSUFFICIENT_BALANCE");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint value) external returns (bool) {
        require(balanceOf[from] >= value, "INSUFFICIENT_BALANCE");
        require(allowance[from][msg.sender] >= value, "INSUFFICIENT_ALLOWANCE");

        allowance[from][msg.sender] -= value;
        balanceOf[from] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
        return true;
    }

    // -----------------------
    // Reserves logic
    // -----------------------
    function _update(uint balance0, uint balance1) private {
        require(balance0 <= type(uint112).max && balance1 <= type(uint112).max, "OVERFLOW");
        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        emit Sync(reserve0, reserve1);
    }

    function getReserves() public view returns (uint112, uint112) {
        return (reserve0, reserve1);
    }

    // -----------------------
    // Mint LP (add liquidity)
    // -----------------------
    function mint(address to) external returns (uint liquidity) {
        (uint112 _reserve0, uint112 _reserve1) = getReserves();
        uint balance0 = IERC20Minimal(token0).balanceOf(address(this));
        uint balance1 = IERC20Minimal(token1).balanceOf(address(this));
        uint amount0 = balance0 - _reserve0;
        uint amount1 = balance1 - _reserve1;

        if (totalSupply == 0) {
            liquidity = sqrt(amount0 * amount1);
        } else {
            uint liquidity0 = (amount0 * totalSupply) / _reserve0;
            uint liquidity1 = (amount1 * totalSupply) / _reserve1;
            liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
        }

        require(liquidity > 0, "INSUFFICIENT_LIQUIDITY_MINTED");
        balanceOf[to] += liquidity;
        totalSupply += liquidity;

        _update(balance0, balance1);
        emit Mint(msg.sender, amount0, amount1, to);
        emit Transfer(address(0), to, liquidity);
    }

    // -----------------------
    // Burn LP (remove liquidity)
    // -----------------------
    function burn(address to) external returns (uint amount0, uint amount1) {
        uint liquidity = balanceOf[address(this)];
        require(liquidity > 0, "NO_LIQUIDITY");

        (uint112 _reserve0, uint112 _reserve1) = getReserves();
        uint balance0 = IERC20Minimal(token0).balanceOf(address(this));
        uint balance1 = IERC20Minimal(token1).balanceOf(address(this));

        amount0 = (liquidity * balance0) / totalSupply;
        amount1 = (liquidity * balance1) / totalSupply;

        require(amount0 > 0 && amount1 > 0, "INSUFFICIENT_BURN_AMOUNT");

        balanceOf[address(this)] -= liquidity;
        totalSupply -= liquidity;
        emit Transfer(address(this), address(0), liquidity);

        IERC20Minimal(token0).transfer(to, amount0);
        IERC20Minimal(token1).transfer(to, amount1);

        balance0 = IERC20Minimal(token0).balanceOf(address(this));
        balance1 = IERC20Minimal(token1).balanceOf(address(this));
        _update(balance0, balance1);

        emit Burn(msg.sender, amount0, amount1, to);
    }

    // -----------------------
    // Swap logic (x * y = k)
    // -----------------------
    function swap(uint amount0Out, uint amount1Out, address to) external {
        require(amount0Out > 0 || amount1Out > 0, "INSUFFICIENT_OUTPUT");
        (uint112 _reserve0, uint112 _reserve1) = getReserves();
        require(amount0Out < _reserve0 && amount1Out < _reserve1, "INSUFFICIENT_LIQUIDITY");

        if (amount0Out > 0) IERC20Minimal(token0).transfer(to, amount0Out);
        if (amount1Out > 0) IERC20Minimal(token1).transfer(to, amount1Out);

        uint balance0 = IERC20Minimal(token0).balanceOf(address(this));
        uint balance1 = IERC20Minimal(token1).balanceOf(address(this));

        uint amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
        uint amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
        require(amount0In > 0 || amount1In > 0, "INSUFFICIENT_INPUT");

        // apply 0.3% fee
        uint balance0Adjusted = (balance0 * 1000) - (amount0In * 3);
        uint balance1Adjusted = (balance1 * 1000) - (amount1In * 3);
        require(
            balance0Adjusted * balance1Adjusted >= uint(_reserve0) * uint(_reserve1) * (1000**2),
            "K"
        );

        _update(balance0, balance1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    // -----------------------
    // Utility
    // -----------------------
    function sqrt(uint y) internal pure returns (uint z) {
        if (y > 3) {
            z = y;
            uint x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

contracts/AMMRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

import "./IERC20Minimal.sol";
import "./AMMFactory.sol";
import "./AMMPair.sol";

contract AMMRouter {
    address public factory;

    constructor(address _factory) {
        factory = _factory;
    }

    // helper: ensure pair exists
    function _pairFor(address tokenA, address tokenB) internal view returns (address) {
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        return AMMFactory(factory).getPair(token0, token1);
    }

    // add liquidity
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint amountA,
        uint amountB,
        address to
    ) external returns (uint liquidity) {
        address pair = _pairFor(tokenA, tokenB);
        require(pair != address(0), "PAIR_NOT_EXIST");

        IERC20Minimal(tokenA).transferFrom(msg.sender, pair, amountA);
        IERC20Minimal(tokenB).transferFrom(msg.sender, pair, amountB);
        liquidity = AMMPair(pair).mint(to);
    }

    // NEW: remove liquidity
    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint liquidity,
        address to
    ) external returns (uint amountA, uint amountB) {
        address pair = _pairFor(tokenA, tokenB);
        require(pair != address(0), "PAIR_NOT_EXIST");

        // transfer LP tokens from user to pair
        AMMPair(pair).transferFrom(msg.sender, pair, liquidity);
        (amountA, amountB) = AMMPair(pair).burn(to);
    }

    // swapExactTokensForTokens(simple single-hop)
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address pathFrom,
        address pathTo,
        address to
    ) external returns (uint amountOut) {
        address pair = _pairFor(pathFrom, pathTo);
        require(pair != address(0), "PAIR_NOT_EXIST");

        // transfer input to pair
        IERC20Minimal(pathFrom).transferFrom(msg.sender, pair, amountIn);

        (uint112 reserve0, uint112 reserve1) = AMMPair(pair).getReserves();
        (address token0, ) = pathFrom < pathTo ? (pathFrom, pathTo) : (pathTo, pathFrom);
        uint reserveIn = pathFrom == token0 ? reserve0 : reserve1;
        uint reserveOut = pathFrom == token0 ? reserve1 : reserve0;

        // Uniswap-like formula with 0.3% fee
        uint amountInWithFee = amountIn * 997;
        uint numerator = amountInWithFee * reserveOut;
        uint denominator = (reserveIn * 1000) + amountInWithFee;
        amountOut = numerator / denominator;
        require(amountOut >= amountOutMin, "INSUFFICIENT_OUTPUT");

        if (pathFrom == token0) {
            AMMPair(pair).swap(0, amountOut, to);
        } else {
            AMMPair(pair).swap(amountOut, 0, to);
        }
    }
}

contracts/IERC20Minimal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

interface IERC20Minimal {
    function totalSupply() external view returns (uint);
    function balanceOf(address owner) external view returns (uint);
    function transfer(address to, uint value) external returns (bool);
    function approve(address spender, uint value) external returns (bool);
    function transferFrom(address from, address to, uint value) external returns (bool);
    function decimals() external view returns (uint8);
    event Transfer(address indexed from, address indexed to, uint value);
    event Approval(address indexed owner, address indexed spender, uint value);
}

